import { Fragment } from "react";
import Link from "next/link";
import { CATALOG, pageDescription } from "@site/lib/catalog";
import { pageMetadata } from "@site/lib/seo";
import { CodeBlock } from "@site/components/code-block";
import { DocPage } from "@site/components/doc-page";
import type { TocGroup } from "@site/components/page-toc";
import { ReferenceTable, type ReferenceRow } from "@site/components/reference-table";
// generated by `pnpm changelog` from each item's changelog[] (scripts/changelog.ts); never edited by hand
import changelog from "@site/lib/changelog.json";

export const metadata = pageMetadata({
  title: "Changelog",
  description: pageDescription("/docs/changelog"),
  path: "/docs/changelog",
});

type Migration = { diff: string; readd: string; modified: string; prompt: string };
type Entry = { item: string; version: string; note: string; breaking: boolean; migration?: Migration };
const releases: { date: string; entries: Entry[] }[] = changelog.releases;

/** The component page an item's entry links to, where one exists. */
const pageOf = new Map(CATALOG.flatMap((g) => g.items.flatMap((e) => (e.href ? [[e.item, e.href] as const] : []))));

const dateId = (date: string) => `d-${date}`;
const longDate = (date: string) =>
  new Date(`${date}T00:00:00Z`).toLocaleDateString("en-GB", {
    day: "numeric",
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  });

function rows(entries: Entry[]): ReferenceRow[] {
  return entries.map((e) => {
    const href = pageOf.get(e.item);
    return {
      name: href ? <Link href={href}>{e.item}</Link> : <code>{e.item}</code>,
      value: <code>{e.version}</code>,
      description: e.breaking ? (
        <>
          <strong>Breaking:</strong> {e.note} <a href={`#${e.item}-${e.version}`}>Migration</a>
        </>
      ) : (
        e.note
      ),
    };
  });
}

const TOC: TocGroup[] = [
  { label: "Changelog", items: releases.map((r) => ({ id: dateId(r.date), label: longDate(r.date) })) },
];

export default function ChangelogPage() {
  return (
    <DocPage name="Changelog" toc={TOC}>
      <h1>Changelog</h1>
      <p className="s-doc-lede">
        Every Keyline item has its own version. Each change to what an item installs bumps it and adds a line here,
        newest first. A breaking entry says how to update code you already copied, with a prompt for an agent.
      </p>
      <p>
        <a href="/r/versions.json">/r/versions.json</a> lists each item&apos;s current version and history, to compare
        with the copy in your project.
      </p>

      {releases.map(({ date, entries }) => (
        <Fragment key={date}>
          <h2 id={dateId(date)}>{longDate(date)}</h2>
          <ReferenceTable
            label={`Changes on ${longDate(date)}`}
            head={["Item", "Version", "Change"]}
            rows={rows(entries)}
          />
          {entries.map((e) =>
            e.migration ? (
              <div key={`${e.item}-${e.version}`}>
                <h3 id={`${e.item}-${e.version}`}>
                  {e.item} {e.version}: migration
                </h3>
                <p>{e.note}</p>
                <CodeBlock code={e.migration.diff} lang="text" copyLabel="migration diff" />
                <p>Re-add it:</p>
                <CodeBlock code={e.migration.readd} lang="bash" copyLabel="re-add command" />
                <p>If you keep a locally modified copy:</p>
                <CodeBlock code={e.migration.modified} lang="text" copyLabel="diff for a modified copy" />
                <p>Agent prompt:</p>
                <CodeBlock code={e.migration.prompt} lang="text" copyLabel="agent prompt" />
              </div>
            ) : null,
          )}
        </Fragment>
      ))}
    </DocPage>
  );
}
